{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "CC-292, a covalent BTK inhibitor with an acrylamide and aminopyrimidine core, demonstrated excellent oral bioavailability in a human Phase I study, directly supporting high F for the query's similar covalent inhibitor scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Golidocitinib, a heteroaryl pyrimidine kinase inhibitor, had >80% oral bioavailability in healthy participants based on a radiolabeled mass balance study, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Brigatinib, a pyrimidine-based kinase inhibitor with a solubilizing piperazine/piperidine side chain, had an estimated 46% oral bioavailability in healthy volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Alisertib, a pyrimidine/quinazoline kinase inhibitor, had a model-estimated bioavailability of 0.671 in pediatric patients, well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Zongertinib, a covalent acrylamide-containing HER2 inhibitor, was predicted to have 41% human oral bioavailability from cross-species PK, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Afatinib, a covalent acrylamide-containing kinase inhibitor, showed good oral bioavailability in Phase I human studies, supporting high F for the acrylamide covalent inhibitor class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Tariquidar had low oral bioavailability in humans, but its large polycyclic P-gp inhibitor structure and low similarity to the query limit transfer; this is the main contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is an acrylamide-containing covalent kinase inhibitor with a pyrimidine core and basic solubilizing amine. Validated human and cross-species evidence for structurally related covalent inhibitors (CC-292, afatinib, zongertinib) and other heteroaryl kinase inhibitors (golidocitinib, brigatinib, alisertib) consistently shows oral bioavailability well above 20% (excellent, >80%, 46-67%, 41%). The only low-F analogue, tariquidar, is a large P-gp substrate with low structural transfer. Therefore high F is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself.",
    "Most transferable analogues have Morgan similarity below 0.3, limiting quantitative extrapolation.",
    "Some supportive records are qualitative ('excellent', 'good') rather than quantitative absolute F.",
    "Several retrieved records appear mismatched with their displayed SMILES and were not used as primary evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

